/**
 * src/save/missionCatalog.js — loads content/missions/missions.json once (generated by tools/extract_missions.py).
 * A failed load rejects and stays visible to the caller: the log shows it, rather than reading as "no missions".
 */
let pending = null;

export function loadMissionCatalog() {
  if (!pending) {
    pending = fetch(new URL('../../content/missions/missions.json', import.meta.url)).then((r) => {
      if (!r.ok) throw new Error('missions.json: HTTP ' + r.status);
      return r.json();
    });
    pending.catch(() => { pending = null; });   // a later open may retry
  }
  return pending;
}
